using System;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmAdminLogin:StyledForm {
 public FrmAdminLogin(){Text="Admin Login";ClientSize=new Size(480,390);MinimumSize=new Size(480,390);MaximumSize=new Size(480,390);StartPosition=FormStartPosition.CenterParent;BackColor=Color.White;MaximizeBox=false;var header=new Panel{Dock=DockStyle.Top,Height=82,BackColor=UiTheme.Navy};header.Controls.Add(new Label{Text="Administrator Access",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.White,Font=new Font("Segoe UI",18,FontStyle.Bold)});Controls.Add(header);var card=new Panel{Location=new Point(62,105),Size=new Size(355,245),BackColor=Color.White};var lblUser=new Label{Text="Username",Location=new Point(10,10),AutoSize=true,Font=new Font("Segoe UI",10,FontStyle.Bold)};var username=new TextBox{Location=new Point(10,35),Size=new Size(335,28),Text="admin",Font=new Font("Segoe UI",10)};var lblPassword=new Label{Text="Password",Location=new Point(10,76),AutoSize=true,Font=new Font("Segoe UI",10,FontStyle.Bold)};var password=new TextBox{Location=new Point(10,101),Size=new Size(335,28),UseSystemPasswordChar=true,Font=new Font("Segoe UI",10)};var login=new Button{Text="Login",Location=new Point(10,148),Size=new Size(335,43),BackColor=UiTheme.Blue,ForeColor=Color.White,FlatStyle=FlatStyle.Flat,Font=new Font("Segoe UI",11,FontStyle.Bold)};login.FlatAppearance.BorderSize=0;var demo=new Label{Text="Demo account: admin / Admin@123",Location=new Point(10,207),Size=new Size(335,24),TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.DimGray};card.Controls.Add(lblUser);card.Controls.Add(username);card.Controls.Add(lblPassword);card.Controls.Add(password);card.Controls.Add(login);card.Controls.Add(demo);Controls.Add(card);AcceptButton=login;login.Click+=delegate{try{if(new UserQuery().Authenticate(username.Text.Trim(),password.Text)){Hide();new FrmAdminDashboard().ShowDialog(this);Close();}else MessageBox.Show("Invalid username or password.\r\nDemo login: admin / Admin@123","Login Failed",MessageBoxButtons.OK,MessageBoxIcon.Warning);}catch(Exception ex){MessageBox.Show("Login could not access the database.\r\n"+ex.Message,"Database Error",MessageBoxButtons.OK,MessageBoxIcon.Error);}};Shown+=delegate{password.Focus();};}
} }
